/* @socom-skeleton body Scale__6CPnt3DCFfP6CPnt3D */
void CPnt3D::Scale(float scaleFactor, CPnt3D *out) const
{
	out->x = x * scaleFactor;
	out->y = y * scaleFactor;
	out->z = z * scaleFactor;
}

/* @socom-skeleton body Normalize__6CPnt3DFv */
float CPnt3D::Normalize()
{
	/* 0x222d40: returns the length before normalizing (the sqrtf result stays in f0) */
	f32 length = sqrtf(x * x + y * y + z * z);

	if (length != 0.0f)
	{
		f32 inv = 1.0f / length;
		x *= inv;
		y *= inv;
		z *= inv;
	}

	return length;
}

/* @socom-skeleton body Normalize__6CPnt3DCFP6CPnt3D */
float CPnt3D::Normalize(CPnt3D *other) const
{
	/* 0x222cb0: the unit vector into other (left alone for a zero vector); returns the
	 * length (f0 still holds sqrtf's result; was a STOPping non-void stub) */
	f32 length = sqrtf(x * x + y * y + z * z);

	if (length != 0.0f)
	{
		f32 inv = 1.0f / length;
		other->x = x * inv;
		other->y = y * inv;
		other->z = z * inv;
	}

	return length;
}

/* @socom-skeleton body Interp__6CPnt3DCFPC6CPnt3DfP6CPnt3D */
void CPnt3D::Interp(const CPnt3D *from, float step, CPnt3D *to) const
{
	if (step == 0.0f)
	{
		to = const_cast<CPnt3D*>(this); /* port: const_cast for GCC; assignment to the local pointer kept as written */
	}
	else
	{
		f32 value = 1.0f - step;

		if (step == 1.0f)
		{
			to->x = from->x;
			to->y = from->y;
			to->z = from->z;
		}
		else
		{
			to->x = x * value;
			to->y = y * value;
			to->z = z * value;

			to->x += from->x * step;
			to->y += from->y * step;
			to->z += from->z * step;
		}
	}
}

/* @socom-skeleton stub Reflect__6CPnt3DFPC6CPnt3D */
CPnt3D CPnt3D::Reflect(const CPnt3D *normal)
{
	/* 0x222b10: this mirrored about the plane of the (unit) normal: this - 2 (this . n) n */
	f32 d = -2.0f * (x * normal->x + y * normal->y + z * normal->z);
	CPnt3D result;
	result.x = normal->x * d + x;
	result.y = normal->y * d + y;
	result.z = normal->z * d + z;
	return result;
}

